+
+const VERSION: &str = "1.4.1";
+const HELP_TEXT: &str = "  json-tui {OPTIONS} [file]
+
+    A JSON terminal UI
+
+  OPTIONS:
+
+      file                              A JSON file. Omit to read from stdin.
+      -h, --help                        Display this help menu.
