+const KEYBINDING_TEXT: &str = "┌───────────┬────────────────┐
+│\u{1b}[36m\u{1b}[49mkeys       \u{1b}[39m\u{1b}[49m│\u{1b}[36m\u{1b}[49maction          \u{1b}[39m\u{1b}[49m│
+├───────────┼────────────────┤
+│Navigate   │← ↑ ↓ →         │
+│           │h j k l         │
+│           │Mouse::WheelUp  │
+│           │Mouse::WheelDown│
+├───────────┼────────────────┤
+│Toggle     │enter           │
+│           │Mouse::Left     │
+├───────────┼────────────────┤
+│Deep       │                │
+│ - Expand  │+               │
+│ - Collapse│-               │
+├───────────┼────────────────┤
+│Exit       │Escape          │
+│           │q               │
+├───────────┼────────────────┤
+│Navigate   │                │
+│ - first   │page-up         │
+│ - last    │page-down       │
+│ - top     │gg              │
+│ - bottom  │G               │
+└───────────┴────────────────┘\0";
+
+const KEY_COLOR: Color = Color::AnsiValue(12);
+const NUMBER_COLOR: Color = Color::AnsiValue(14);
+const BOOL_COLOR: Color = Color::AnsiValue(11);
+const STRING_COLOR: Color = Color::AnsiValue(10);
+const NULL_COLOR: Color = Color::AnsiValue(9);
+const HINT_COLOR: Color = Color::AnsiValue(8);
+
+type Path = Vec<PathPart>;
+
+#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd, Hash)]
+enum PathPart {
+    Key(String),
+    Index(usize),
+}
+
+#[derive(Clone, Debug)]
+enum JsonNode {
+    Null,
+    Bool(bool),
+    Number(String),
+    String(String),
+    Array(Vec<JsonNode>),
+    Object(Vec<(String, JsonNode)>),
+}
+
+#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd, Hash)]
+struct TableCellPath {
+    array_path: Path,
+    row: usize,
+    column: String,
+    inner_path: Path,
+}
+
+#[derive(Clone, Debug, Eq, PartialEq)]
+enum Focus {
+    TreeNode { path: Path, toggle: bool },
+    TableToggle { path: Path },
+    TableCell { path: Path, row: usize, column: usize },
+}
+
+#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
+enum VerticalItemKey {
+    TreeNode(Path),
+    TableToggle(Path),
+    TableRow { path: Path, row: usize },
+}
+
+#[derive(Clone, Debug)]
+struct VerticalItem {
+    key: VerticalItemKey,
+    start_line: usize,
+    end_line: usize,
+    column_count: usize,
+}
+
+#[derive(Clone, Debug, Default, Eq, PartialEq)]
+struct Face {
+    fg: Option<Color>,
+    bold: bool,
+    reverse: bool,
+}
+
+#[derive(Clone, Debug)]
+struct Segment {
+    text: String,
+    face: Face,
+}
+
+#[derive(Clone, Debug, Default)]
+struct StyledLine {
+    segments: Vec<Segment>,
+    width: usize,
+}
+
+#[derive(Clone, Debug, Default)]
+struct RenderOutput {
+    lines: Vec<StyledLine>,
+    vertical_items: Vec<VerticalItem>,
+}
+
+#[derive(Clone, Debug)]
+struct App {
+    root: JsonNode,
+    fullscreen: bool,
+    expanded: BTreeSet<Path>,
+    table_mode: BTreeSet<Path>,
+    expanded_cells: BTreeSet<TableCellPath>,
+    focus: Focus,
+    scroll: usize,
+    pending_g: bool,
+}
+
+#[derive(Clone, Debug, Default)]
+struct Options {
+    fullscreen: bool,
+    action: Action,
+    file: Option<String>,
+}
+
+#[derive(Clone, Debug, Default)]
+enum Action {
+    #[default]
+    Run,
+    Help,
+    Version,
+    Keybinding,
+}
+
+struct TerminalGuard {
+    stdout: Stdout,
+    fullscreen: bool,
+    start_row: u16,
+    width: u16,
+    height: u16,
+    last_drawn_lines: u16,
+}
+
+impl Face {
+    fn with_reverse(&self, enabled: bool) -> Self {
+        let mut face = self.clone();
+        face.reverse = enabled;
+        face
+    }
+
+    fn with_bold(mut self) -> Self {
+        self.bold = true;
+        self
+    }
+}
+
+impl StyledLine {
+    fn push(&mut self, text: impl Into<String>, face: Face) {
+        let text = text.into();
+        if text.is_empty() {
+            return;
+        }
+        self.width += UnicodeWidthStr::width(text.as_str());
+        if let Some(last) = self.segments.last_mut() {
+            if last.face == face {
+                last.text.push_str(&text);
+                return;
+            }
+        }
+        self.segments.push(Segment { text, face });
+    }
+}
+
+impl App {
+    fn new(root: JsonNode, fullscreen: bool) -> Self {
+        let mut expanded = BTreeSet::new();
+        collect_default_expansions(&root, &Vec::new(), &mut expanded);
+        Self {
+            root,
+            fullscreen,
+            expanded,
+            table_mode: BTreeSet::new(),
+            expanded_cells: BTreeSet::new(),
+            focus: Focus::TreeNode {
+                path: Vec::new(),
+                toggle: false,
+            },
+            scroll: 0,
+            pending_g: false,
+        }
+    }
+
+    fn run(&mut self) -> io::Result<()> {
+        let (width, height) = terminal::size().unwrap_or((80, 24));
+        let start_row = if self.fullscreen {
+            0
+        } else {
+            cursor::position().map(|(_, y)| y).unwrap_or(0)
+        };
+
+        enable_raw_mode()?;
+        let mut guard = TerminalGuard {
+            stdout: io::stdout(),
+            fullscreen: self.fullscreen,
+            start_row,
+            width,
+            height,
+            last_drawn_lines: 0,
+        };
+        guard.enter()?;
+        self.render(&mut guard)?;
+
+        let loop_result = self.event_loop(&mut guard);
+        let exit_result = guard.leave();
+        loop_result?;
+        exit_result
+    }
+
+    fn event_loop(&mut self, guard: &mut TerminalGuard) -> io::Result<()> {
+        loop {
+            if event::poll(Duration::from_millis(250))? {
+                match event::read()? {
+                    Event::Key(key) if key.kind == KeyEventKind::Press => {
+                        if self.handle_key(key, guard.height as usize) {
+                            return Ok(());
+                        }
+                        self.render(guard)?;
+                    }
+                    Event::Mouse(mouse) => {
+                        match mouse.kind {
+                            MouseEventKind::ScrollUp => self.move_vertical(-1),
+                            MouseEventKind::ScrollDown => self.move_vertical(1),
+                            MouseEventKind::Down(MouseButton::Left) => {
+                                self.handle_click(mouse.column as usize, mouse.row as usize, guard);
+                            }
+                            _ => {}
+                        }
+                        self.pending_g = false;
+                        self.render(guard)?;
+                    }
+                    Event::Resize(width, height) => {
+                        guard.width = width;
+                        guard.height = height;
+                        self.render(guard)?;
+                    }
+                    _ => {}
+                }
+            }
+        }
+    }
+
+    fn handle_key(&mut self, key: KeyEvent, viewport_height: usize) -> bool {
+        match key.code {
+            KeyCode::Char('q') | KeyCode::Esc => return true,
+            KeyCode::Up => self.move_vertical(-1),
+            KeyCode::Down => self.move_vertical(1),
+            KeyCode::PageUp => self.page_move(-(viewport_height as isize)),
+            KeyCode::PageDown => self.page_move(viewport_height as isize),
+            KeyCode::Left => self.move_horizontal(-1),
+            KeyCode::Right => self.move_horizontal(1),
+            KeyCode::Enter => self.activate_selection(),
+            KeyCode::Char('+') => self.deep_expand_selection(),
+            KeyCode::Char('-') => self.deep_collapse_selection(),
+            KeyCode::Char('j') => self.move_vertical(1),
+            KeyCode::Char('k') => self.move_vertical(-1),
+            KeyCode::Char('h') => self.move_horizontal(-1),
+            KeyCode::Char('l') => self.move_horizontal(1),
+            KeyCode::Char('g') => {
+                if self.pending_g {
+                    self.pending_g = false;
+                    self.jump_top();
+                } else {
+                    self.pending_g = true;
+                    return false;
+                }
+            }
+            KeyCode::Char('G') => self.jump_bottom(),
+            _ => {}
+        }
+        self.pending_g = false;
+        false
+    }
+
+    fn handle_click(&mut self, column: usize, row: usize, guard: &TerminalGuard) {
+        let viewport = self.viewport_height(guard);
+        let width = guard.width as usize;
+        let render = self.build_render(width);
+        let relative_row = row.saturating_sub(guard.start_row as usize);
+        if relative_row >= viewport {
+            return;
+        }
+        let line_index = self.scroll + relative_row;
+        for item in &render.vertical_items {
+            if line_index < item.start_line || line_index > item.end_line {
+                continue;
+            }
+            match &item.key {
+                VerticalItemKey::TreeNode(path) => {
+                    let node = get_node(&self.root, path).unwrap_or(&self.root);
+                    if !self.is_table_toggle_available(path, node) {
+                        self.focus = Focus::TreeNode {
+                            path: path.clone(),
+                            toggle: false,
+                        };
+                        self.activate_selection();
+                        return;
+                    }
+                    let toggle_start = tree_toggle_start(path);
+                    let on_toggle = column >= toggle_start;
+                    let new_focus = Focus::TreeNode {
+                        path: path.clone(),
+                        toggle: on_toggle,
+                    };
+                    if self.focus == new_focus {
+                        self.activate_selection();
+                    } else {
+                        self.focus = new_focus;
+                    }
+                    return;
+                }
+                VerticalItemKey::TableToggle(path) => {
+                    let new_focus = Focus::TableToggle { path: path.clone() };
+                    if self.focus == new_focus {
+                        self.activate_selection();
+                    } else {
+                        self.focus = new_focus;
+                    }
+                    return;
+                }
+                VerticalItemKey::TableRow { path, row } => {
+                    let columns = table_columns(get_node(&self.root, path).unwrap());
+                    if columns.is_empty() {
+                        return;
+                    }
+                    let clicked_column = detect_table_column(path, &columns, column);
+                    let new_focus = Focus::TableCell {
+                        path: path.clone(),
+                        row: *row,
+                        column: clicked_column.min(columns.len() - 1),
+                    };
+                    if self.focus == new_focus {
+                        self.activate_selection();
+                    } else {
+                        self.focus = new_focus;
+                    }
+                    return;
+                }
+            }
+        }
+    }
+
+    fn viewport_height(&self, guard: &TerminalGuard) -> usize {
+        if self.fullscreen {
+            guard.height as usize
+        } else {
+            guard.height.saturating_sub(guard.start_row).max(1) as usize
+        }
+    }
+
+    fn render(&mut self, guard: &mut TerminalGuard) -> io::Result<()> {
+        let width = guard.width.max(1) as usize;
+        let render = self.build_render(width);
+        self.clamp_focus(&render);
+        self.adjust_scroll(&render, self.viewport_height(guard));
+
+        let viewport_height = self.viewport_height(guard);
+        let total_visible = render.lines.len().saturating_sub(self.scroll);
+        let draw_count = total_visible.min(viewport_height);
+        let clear_count = draw_count.max(guard.last_drawn_lines as usize);
+
+        for row in 0..clear_count {
+            queue!(
+                guard.stdout,
+                MoveTo(0, guard.start_row.saturating_add(row as u16)),
+                Clear(ClearType::CurrentLine)
+            )?;
+            if row < draw_count {
+                let line = &render.lines[self.scroll + row];
+                write_styled_line(&mut guard.stdout, line, width)?;
+            }
+        }
+
+        if self.fullscreen {
+            for row in clear_count..viewport_height {
+                queue!(
+                    guard.stdout,
+                    MoveTo(0, guard.start_row.saturating_add(row as u16)),
+                    Clear(ClearType::CurrentLine)
+                )?;
+            }
+        }
+
+        guard.last_drawn_lines = draw_count as u16;
+        guard.stdout.flush()?;
+        Ok(())
+    }
+
+    fn build_render(&self, width: usize) -> RenderOutput {
+        let mut output = RenderOutput::default();
+        let mut path = Vec::new();
+        self.render_tree_node(
+            &mut output,
+            &self.root,
+            &mut path,
+            0,
+            None,
+            true,
+            width,
+        );
+        output
+    }
+
+    #[allow(clippy::too_many_arguments)]
+    fn render_tree_node(
+        &self,
+        output: &mut RenderOutput,
+        node: &JsonNode,
+        path: &mut Path,
+        depth: usize,
+        key: Option<&str>,
+        is_last: bool,
+        width: usize,
+    ) {
+        if matches!(node, JsonNode::Array(_))
+            && self.table_mode.contains(path)
+            && self.is_table_toggle_available(path, node)
+        {
+            self.render_table_view(output, node, path, depth, key, is_last, width);
+            return;
+        }
+
+        let item_start = output.lines.len();
+        match node {
+            JsonNode::Null | JsonNode::Bool(_) | JsonNode::Number(_) | JsonNode::String(_) => {
+                self.render_primitive(output, node, path, depth, key, is_last, width);
+            }
+            JsonNode::Array(values) => {
+                let expanded = self.expanded.contains(path);
+                self.render_container(
+                    output,
+                    node,
+                    path,
+                    depth,
+                    key,
+                    is_last,
+                    width,
+                    '[',
+                    ']',
+                    values.iter().enumerate().map(|(index, child)| {
+                        (PathPart::Index(index), None::<String>, child)
+                    }),
+                    expanded,
+                );
+            }
+            JsonNode::Object(entries) => {
+                let expanded = self.expanded.contains(path);
+                self.render_container(
+                    output,
+                    node,
+                    path,
+                    depth,
+                    key,
+                    is_last,
+                    width,
+                    '{',
+                    '}',
+                    entries.iter().map(|(name, child)| {
+                        (PathPart::Key(name.clone()), Some(name.clone()), child)
+                    }),
+                    expanded,
+                );
+            }
+        }
+        let item_end = output.lines.len().saturating_sub(1);
+        output.vertical_items.push(VerticalItem {
+            key: VerticalItemKey::TreeNode(path.clone()),
+            start_line: item_start,
+            end_line: item_end.max(item_start),
+            column_count: 1,
+        });
+    }
+
+    fn render_primitive(
+        &self,
+        output: &mut RenderOutput,
+        node: &JsonNode,
+        path: &Path,
+        depth: usize,
+        key: Option<&str>,
+        is_last: bool,
+        width: usize,
+    ) {
+        let serialized = serialize_node(node);
+        let face = primitive_face(node);
+        let selected = matches!(
+            self.focus,
+            Focus::TreeNode {
+                path: ref focus_path,
+                toggle: false
+            } if focus_path == path
+        );
+        let prefix = line_prefix(depth, key);
+        let continuation = continuation_prefix(depth, key);
+        let prefix_width = prefix_width(depth, key);
+        let first_width = width.saturating_sub(prefix_width).max(1);
+        let continuation_width = width.saturating_sub(continuation.width).max(1);
+        let wrapped = wrap_text(&serialized, first_width, continuation_width);
+
+        for (index, chunk) in wrapped.iter().enumerate() {
+            let mut line = StyledLine::default();
+            if index == 0 {
+                push_prefix(&mut line, &prefix);
+            } else {
+                push_prefix(&mut line, &continuation);
+            }
+            let chunk_text = if index == 0 && !is_last {
+                format!("{chunk},")
+            } else {
+                chunk.clone()
+            };
+            line.push(chunk_text, face.with_reverse(selected && index == 0));
+            output.lines.push(line);
+        }
+    }
+
+    #[allow(clippy::too_many_arguments)]
+    fn render_container<'a, I>(
+        &self,
+        output: &mut RenderOutput,
+        node: &JsonNode,
+        path: &mut Path,
+        depth: usize,
+        key: Option<&str>,
+        is_last: bool,
+        width: usize,
+        open: char,
+        close: char,
+        children: I,
+        expanded: bool,
+    ) where
+        I: IntoIterator<Item = (PathPart, Option<String>, &'a JsonNode)>,
+    {
+        let focus_primary = matches!(
+            self.focus,
+            Focus::TreeNode {
+                path: ref focus_path,
+                toggle: false
+            } if focus_path == path
+        );
+        let focus_toggle = matches!(
+            self.focus,
+            Focus::TreeNode {
+                path: ref focus_path,
+                toggle: true
+            } if focus_path == path
+        );
+        let mut line = StyledLine::default();
+        push_prefix(&mut line, &line_prefix(depth, key));
+
+        if expanded {
+            line.push(
+                open.to_string(),
+                Face::default().with_bold().with_reverse(focus_primary),
+            );
+        } else {
+            line.push(
+                collapsed_marker(node).to_string() + if !is_last { "," } else { "" },
+                Face::default().with_bold().with_reverse(focus_primary),
+            );
+        }
+
+        if self.is_table_toggle_available(path, node) {
+            line.push("   ", Face::default());
+            line.push(
+                "(table view)",
+                Face {
+                    fg: Some(HINT_COLOR),
+                    ..Face::default()
+                }
+                .with_reverse(focus_toggle),
+            );
+        }
+        output.lines.push(line);
+
+        if !expanded {
+            return;
+        }
+
+        let children = children.into_iter().collect::<Vec<_>>();
+        for (index, (path_part, child_key, child)) in children.iter().enumerate() {
+            path.push(path_part.clone());
+            self.render_tree_node(
+                output,
+                child,
+                path,
+                depth + 1,
+                child_key.as_deref(),
+                index + 1 == children.len(),
+                width,
+            );
+            path.pop();
+        }
+
+        let mut closing = StyledLine::default();
+        push_indent(&mut closing, depth);
+        let closing_text = if is_last {
+            close.to_string()
+        } else {
+            format!("{close},")
+        };
+        closing.push(closing_text, Face::default());
+        output.lines.push(closing);
+    }
+
+    fn render_table_view(
+        &self,
+        output: &mut RenderOutput,
+        node: &JsonNode,
+        path: &mut Path,
+        depth: usize,
+        key: Option<&str>,
+        is_last: bool,
+        width: usize,
+    ) {
+        let toggle_line = output.lines.len();
+        let mut line = StyledLine::default();
+        push_prefix(&mut line, &line_prefix(depth, key));
+        line.push(
+            "(array view)",
+            Face {
+                fg: Some(HINT_COLOR),
+                ..Face::default()
+            }
+            .with_reverse(matches!(
+                self.focus,
+                Focus::TableToggle { path: ref focus_path } if focus_path == path
+            )),
+        );
+        output.lines.push(line);
+        output.vertical_items.push(VerticalItem {
+            key: VerticalItemKey::TableToggle(path.clone()),
+            start_line: toggle_line,
+            end_line: toggle_line,
+            column_count: 1,
+        });
+
+        let JsonNode::Array(rows) = node else {
+            return;
+        };
+        let columns = table_columns(node);
+        if columns.is_empty() {
+            return;
+        }
+
+        let mut blocks = Vec::new();
+        let mut col_widths = columns
+            .iter()
+            .map(|column| UnicodeWidthStr::width(column.as_str()))
+            .collect::<Vec<_>>();
+        for (row_index, row) in rows.iter().enumerate() {
+            let JsonNode::Object(entries) = row else {
+                continue;
+            };
+            let entry_map = entries
+                .iter()
+                .map(|(name, value)| (name.as_str(), value))
+                .collect::<BTreeMap<_, _>>();
+            let mut row_blocks = Vec::new();
+            for (col_index, column) in columns.iter().enumerate() {
+                let value = entry_map.get(column.as_str()).copied();
+                let block = self.render_table_cell_block(path, row_index, column, value, width);
+                col_widths[col_index] = col_widths[col_index].max(block_max_width(&block));
+                row_blocks.push(block);
+            }
+            blocks.push(row_blocks);
+        }
+
+        let index_width = rows.len().saturating_sub(1).to_string().len().max(1);
+        let table_indent = depth * 2 + index_width;
+        output.lines.push(table_border_line(table_indent, &col_widths, '┏', '┳', '┓'));
+        output.lines.push(table_header_line(
+            depth * 2,
+            index_width,
+            &columns,
+            &col_widths,
+        ));
+        output.lines.push(table_border_line(table_indent, &col_widths, '┡', '╇', '┩'));
+
+        for (row_index, row_blocks) in blocks.iter().enumerate() {
+            let start_line = output.lines.len();
+            let row_height = row_blocks.iter().map(|block| block.len()).max().unwrap_or(1);
+            for subline in 0..row_height {
+                let mut line = StyledLine::default();
+                push_spaces(&mut line, depth * 2);
+                if subline == 0 {
+                    let label = format!("{row_index:>index_width$}");
+                    line.push(
+                        label,
+                        Face {
+                            fg: Some(HINT_COLOR),
+                            ..Face::default()
+                        },
+                    );
+                } else {
+                    line.push(
+                        " ".repeat(index_width),
+                        Face {
+                            fg: Some(HINT_COLOR),
+                            ..Face::default()
+                        },
+                    );
+                }
+                line.push("│", Face::default());
+                for (column_index, block) in row_blocks.iter().enumerate() {
+                    let selected = matches!(
+                        self.focus,
+                        Focus::TableCell {
+                            path: ref focus_path,
+                            row,
+                            column
+                        } if focus_path == path && row == row_index && column == column_index
+                    );
+                    let cell_line = block.get(subline).cloned().unwrap_or_default();
+                    let cell_width = line_width(&cell_line);
+                    append_segments_with_optional_reverse(
+                        &mut line,
+                        &cell_line,
+                        selected && subline == 0,
+                    );
+                    if col_widths[column_index] > cell_width {
+                        push_spaces(&mut line, col_widths[column_index] - cell_width);
+                    }
+                    line.push("│", Face::default());
+                }
+                output.lines.push(line);
+            }
+            output.vertical_items.push(VerticalItem {
+                key: VerticalItemKey::TableRow {
+                    path: path.clone(),
+                    row: row_index,
+                },
+                start_line,
+                end_line: output.lines.len().saturating_sub(1),
+                column_count: columns.len(),
+            });
+        }
+
+        output.lines.push(table_border_line(table_indent, &col_widths, '└', '┴', '┘'));
+        if !is_last {
+            if let Some(last) = output.lines.last_mut() {
+                last.push(",", Face::default());
+            }
+        }
+    }
