        let first_width = width.saturating_sub(prefix_width).max(1);
        let continuation_width = width.saturating_sub(continuation.width).max(1);
        let wrapped = wrap_text(&serialized, first_width, continuation_width);

        for (index, chunk) in wrapped.iter().enumerate() {
            let mut line = StyledLine::default();
            if index == 0 {
                push_prefix(&mut line, &prefix);
            } else {
                push_prefix(&mut line, &continuation);
            }
            let chunk_text = if index == 0 && !is_last {
                format!("{chunk},")
            } else {
                chunk.clone()
            };
            line.push(chunk_text, face.with_reverse(selected && index == 0));
            output.lines.push(line);
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn render_container<'a, I>(
        &self,
        output: &mut RenderOutput,
        node: &JsonNode,
        path: &mut Path,
        depth: usize,
        key: Option<&str>,
        is_last: bool,
        width: usize,
        open: char,
        close: char,
        children: I,
        expanded: bool,
    ) where
        I: IntoIterator<Item = (PathPart, Option<String>, &'a JsonNode)>,
    {
        let focus_primary = matches!(
            self.focus,
            Focus::TreeNode {
                path: ref focus_path,
                toggle: false
            } if focus_path == path
        );
        let focus_toggle = matches!(
            self.focus,
            Focus::TreeNode {
                path: ref focus_path,
                toggle: true
            } if focus_path == path
        );
        let mut line = StyledLine::default();
        push_prefix(&mut line, &line_prefix(depth, key));

        if expanded {
            line.push(
                open.to_string(),
                Face::default().with_bold().with_reverse(focus_primary),
            );
        } else {
            line.push(
                collapsed_marker(node).to_string() + if !is_last { "," } else { "" },
                Face::default().with_bold().with_reverse(focus_primary),
            );
        }

        if self.is_table_toggle_available(path, node) {
            line.push("   ", Face::default());
            line.push(
                "(table view)",
                Face {
                    fg: Some(HINT_COLOR),
                    ..Face::default()
                }
                .with_reverse(focus_toggle),
            );
        }
        output.lines.push(line);

        if !expanded {
            return;
        }

        let children = children.into_iter().collect::<Vec<_>>();
        for (index, (path_part, child_key, child)) in children.iter().enumerate() {
            path.push(path_part.clone());
            self.render_tree_node(
                output,
                child,
                path,
                depth + 1,
                child_key.as_deref(),
                index + 1 == children.len(),
                width,
            );
            path.pop();
        }

        let mut closing = StyledLine::default();
        push_indent(&mut closing, depth);
        let closing_text = if is_last {
            close.to_string()
        } else {
            format!("{close},")
        };
        closing.push(closing_text, Face::default());
        output.lines.push(closing);
    }

    fn render_table_view(
        &self,
        output: &mut RenderOutput,
        node: &JsonNode,
        path: &mut Path,
        depth: usize,
        key: Option<&str>,
        is_last: bool,
        width: usize,
    ) {
        let toggle_line = output.lines.len();
        let mut line = StyledLine::default();
        push_prefix(&mut line, &line_prefix(depth, key));
        line.push(
            "(array view)",
            Face {
                fg: Some(HINT_COLOR),
                ..Face::default()
            }
            .with_reverse(matches!(
                self.focus,
                Focus::TableToggle { path: ref focus_path } if focus_path == path
            )),
        );
        output.lines.push(line);
        output.vertical_items.push(VerticalItem {
            key: VerticalItemKey::TableToggle(path.clone()),
            start_line: toggle_line,
            end_line: toggle_line,
            column_count: 1,
        });

        let JsonNode::Array(rows) = node else {
            return;
        };
        let columns = table_columns(node);
        if columns.is_empty() {
            return;
        }

        let mut blocks = Vec::new();
        let mut col_widths = columns
            .iter()
            .map(|column| UnicodeWidthStr::width(column.as_str()))
            .collect::<Vec<_>>();
        for (row_index, row) in rows.iter().enumerate() {
            let JsonNode::Object(entries) = row else {
                continue;
            };
            let entry_map = entries
                .iter()
                .map(|(name, value)| (name.as_str(), value))
                .collect::<BTreeMap<_, _>>();
            let mut row_blocks = Vec::new();
            for (col_index, column) in columns.iter().enumerate() {
                let value = entry_map.get(column.as_str()).copied();
                let block = self.render_table_cell_block(path, row_index, column, value, width);
                col_widths[col_index] = col_widths[col_index].max(block_max_width(&block));
                row_blocks.push(block);
            }
            blocks.push(row_blocks);
        }

        let index_width = rows.len().saturating_sub(1).to_string().len().max(1);
        let table_indent = depth * 2 + index_width;
        output.lines.push(table_border_line(table_indent, &col_widths, '┏', '┳', '┓'));
        output.lines.push(table_header_line(
            depth * 2,
            index_width,
            &columns,
            &col_widths,
        ));
        output.lines.push(table_border_line(table_indent, &col_widths, '┡', '╇', '┩'));

        for (row_index, row_blocks) in blocks.iter().enumerate() {
            let start_line = output.lines.len();
            let row_height = row_blocks.iter().map(|block| block.len()).max().unwrap_or(1);
            for subline in 0..row_height {
                let mut line = StyledLine::default();
                push_spaces(&mut line, depth * 2);
                if subline == 0 {
                    let label = format!("{row_index:>index_width$}");
                    line.push(
                        label,
                        Face {
                            fg: Some(HINT_COLOR),
                            ..Face::default()
                        },
                    );
                } else {
                    line.push(
                        " ".repeat(index_width),
                        Face {
                            fg: Some(HINT_COLOR),
                            ..Face::default()
                        },
                    );
                }
                line.push("│", Face::default());
                for (column_index, block) in row_blocks.iter().enumerate() {
                    let selected = matches!(
                        self.focus,
                        Focus::TableCell {
                            path: ref focus_path,
                            row,
                            column
                        } if focus_path == path && row == row_index && column == column_index
                    );
                    let cell_line = block.get(subline).cloned().unwrap_or_default();
                    let cell_width = line_width(&cell_line);
                    append_segments_with_optional_reverse(
                        &mut line,
                        &cell_line,
                        selected && subline == 0,
                    );
                    if col_widths[column_index] > cell_width {
                        push_spaces(&mut line, col_widths[column_index] - cell_width);
                    }
                    line.push("│", Face::default());
                }
                output.lines.push(line);
            }
            output.vertical_items.push(VerticalItem {
                key: VerticalItemKey::TableRow {
                    path: path.clone(),
                    row: row_index,
                },
                start_line,
                end_line: output.lines.len().saturating_sub(1),
                column_count: columns.len(),
            });
        }

        output.lines.push(table_border_line(table_indent, &col_widths, '└', '┴', '┘'));
        if !is_last {
            if let Some(last) = output.lines.last_mut() {
                last.push(",", Face::default());
            }
        }
    }

    fn render_table_cell_block(
        &self,
        array_path: &Path,
        row: usize,
        column: &str,
        value: Option<&JsonNode>,
        width: usize,
    ) -> Vec<StyledLine> {
        let Some(value) = value else {
            return vec![StyledLine::default()];
        };
        let root_path = TableCellPath {
            array_path: array_path.clone(),
            row,
            column: column.to_string(),
            inner_path: Vec::new(),
        };
        render_embedded_value(
            value,
            &root_path,
            &self.expanded_cells,
            width.saturating_sub(4).max(1),
            true,
        )
    }

    fn clamp_focus(&mut self, render: &RenderOutput) {
        if render.vertical_items.is_empty() {
            return;
        }

        match &self.focus {
            Focus::TreeNode { path, toggle } => {
                if render
                    .vertical_items
                    .iter()
                    .any(|item| matches!(&item.key, VerticalItemKey::TreeNode(item_path) if item_path == path))
                {
                    if *toggle && !self.can_focus_toggle(path) {
                        self.focus = Focus::TreeNode {
                            path: path.clone(),
                            toggle: false,
                        };
                    }
                    return;
                }
            }
            Focus::TableToggle { path } => {
                if render
                    .vertical_items
                    .iter()
                    .any(|item| matches!(&item.key, VerticalItemKey::TableToggle(item_path) if item_path == path))
                {
                    return;
                }
            }
            Focus::TableCell { path, row, column } => {
                if let Some(item) = render.vertical_items.iter().find(|item| {
                    matches!(
                        &item.key,
                        VerticalItemKey::TableRow {
                            path: item_path,
                            row: item_row
                        } if item_path == path && item_row == row
                    )
                }) {
                    if *column < item.column_count {
                        return;
                    }
                }
            }
        }

        if let Some(first) = render.vertical_items.first() {
            self.focus = match &first.key {
                VerticalItemKey::TreeNode(path) => Focus::TreeNode {
                    path: path.clone(),
                    toggle: false,
                },
                VerticalItemKey::TableToggle(path) => Focus::TableToggle { path: path.clone() },
                VerticalItemKey::TableRow { path, row } => Focus::TableCell {
                    path: path.clone(),
                    row: *row,
                    column: 0,
                },
            };
        }
    }

    fn adjust_scroll(&mut self, render: &RenderOutput, viewport_height: usize) {
        if render.vertical_items.is_empty() {
            self.scroll = 0;
            return;
        }
        let selected_line = selected_line_index(render, &self.focus);
        if selected_line < self.scroll {
            self.scroll = selected_line;
        } else if selected_line >= self.scroll + viewport_height {
            self.scroll = selected_line.saturating_sub(viewport_height.saturating_sub(1));
        }
        let max_scroll = render.lines.len().saturating_sub(viewport_height);
        self.scroll = self.scroll.min(max_scroll);
    }

    fn move_vertical(&mut self, delta: isize) {
        let render = self.build_render(80);
        if render.vertical_items.is_empty() {
            return;
        }
        let current = selected_vertical_index(&render, &self.focus);
        let next = (current as isize + delta)
            .clamp(0, render.vertical_items.len().saturating_sub(1) as isize) as usize;
        self.focus = focus_for_vertical_item(&render.vertical_items[next], &self.focus);
    }

    fn page_move(&mut self, delta: isize) {
        let render = self.build_render(80);
        if render.vertical_items.is_empty() {
            return;
        }
        let current = selected_vertical_index(&render, &self.focus);
        let next = (current as isize + delta)
            .clamp(0, render.vertical_items.len().saturating_sub(1) as isize) as usize;
        self.focus = focus_for_vertical_item(&render.vertical_items[next], &self.focus);
    }

    fn move_horizontal(&mut self, delta: isize) {
        match &self.focus {
            Focus::TreeNode { path, toggle } => {
                if self.can_focus_toggle(path) {
                    if delta > 0 && !toggle {
                        self.focus = Focus::TreeNode {
                            path: path.clone(),
                            toggle: true,
                        };
                    } else if delta < 0 && *toggle {
                        self.focus = Focus::TreeNode {
                            path: path.clone(),
                            toggle: false,
                        };
                    }
                }
            }
            Focus::TableCell { path, row, column } => {
                let columns = table_columns(get_node(&self.root, path).unwrap());
                if columns.is_empty() {
                    return;
                }
                let next = (*column as isize + delta)
                    .clamp(0, columns.len().saturating_sub(1) as isize) as usize;
                self.focus = Focus::TableCell {
                    path: path.clone(),
                    row: *row,
                    column: next,
                };
            }
            _ => {}
        }
    }

    fn activate_selection(&mut self) {
        match self.focus.clone() {
            Focus::TreeNode { path, toggle } => {
                if toggle {
                    self.table_mode.insert(path.clone());
                    self.expanded.insert(path.clone());
                    self.focus = Focus::TableToggle { path };
                    return;
                }
                if let Some(node) = get_node(&self.root, &path) {
                    if is_container(node) {
                        if self.expanded.contains(&path) {
                            self.expanded.remove(&path);
                        } else {
                            self.expanded.insert(path);
                        }
                    }
                }
            }
            Focus::TableToggle { path } => {
                self.table_mode.remove(&path);
                self.focus = Focus::TreeNode { path, toggle: true };
            }
            Focus::TableCell { path, row, column } => {
                let columns = table_columns(get_node(&self.root, &path).unwrap());
                let Some(column_name) = columns.get(column).cloned() else {
                    return;
                };
                let Some(value) = table_value(get_node(&self.root, &path).unwrap(), row, &column_name) else {
                    return;
                };
                if !is_container(value) {
                    return;
                }
                let root_path = TableCellPath {
                    array_path: path,
                    row,
                    column: column_name,
                    inner_path: Vec::new(),
                };
                if self.expanded_cells.contains(&root_path) {
                    self.remove_cell_prefix(&root_path);
                } else {
                    self.expanded_cells.insert(root_path);
                }
            }
        }
    }

    fn deep_expand_selection(&mut self) {
        match self.focus.clone() {
            Focus::TreeNode { path, toggle: false } => {
                if let Some(node) = get_node(&self.root, &path) {
                    deep_expand_tree(node, &path, &mut self.expanded);
                }
            }
            Focus::TableCell { path, row, column } => {
                let columns = table_columns(get_node(&self.root, &path).unwrap());
                let Some(column_name) = columns.get(column).cloned() else {
                    return;
                };
                let Some(value) = table_value(get_node(&self.root, &path).unwrap(), row, &column_name) else {
                    return;
                };
                let root_path = TableCellPath {
                    array_path: path,
                    row,
                    column: column_name,
                    inner_path: Vec::new(),
                };
                deep_expand_cell(value, &root_path, &mut self.expanded_cells);
            }
            _ => {}
        }
    }

    fn deep_collapse_selection(&mut self) {
        match self.focus.clone() {
            Focus::TreeNode { path, toggle: false } => {
                self.remove_tree_descendants(&path);
            }
            Focus::TableCell { path, row, column } => {
                let columns = table_columns(get_node(&self.root, &path).unwrap());
                let Some(column_name) = columns.get(column).cloned() else {
                    return;
                };
                let root_path = TableCellPath {
                    array_path: path,
                    row,
                    column: column_name,
                    inner_path: Vec::new(),
                };
                self.remove_cell_descendants(&root_path);
            }
            _ => {}
        }
    }

    fn remove_tree_descendants(&mut self, path: &Path) {
        self.expanded = self
            .expanded
            .iter()
            .filter(|candidate| !is_descendant(path, candidate))
            .cloned()
            .collect();
    }

    fn remove_cell_descendants(&mut self, root: &TableCellPath) {
        self.expanded_cells = self
            .expanded_cells
            .iter()
            .filter(|candidate| {
                candidate.array_path != root.array_path
                    || candidate.row != root.row
                    || candidate.column != root.column
                    || !is_descendant(&root.inner_path, &candidate.inner_path)
                    || candidate.inner_path == root.inner_path
            })
            .cloned()
            .collect();
    }

    fn remove_cell_prefix(&mut self, root: &TableCellPath) {
        self.expanded_cells = self
            .expanded_cells
            .iter()
            .filter(|candidate| {
                candidate.array_path != root.array_path
                    || candidate.row != root.row
                    || candidate.column != root.column
                    || !is_descendant_or_same(&root.inner_path, &candidate.inner_path)
            })
            .cloned()
            .collect();
    }

    fn can_focus_toggle(&self, path: &Path) -> bool {
        get_node(&self.root, path)
            .map(|node| self.is_table_toggle_available(path, node) && !self.table_mode.contains(path))
            .unwrap_or(false)
    }

    fn is_table_toggle_available(&self, _path: &Path, node: &JsonNode) -> bool {
        is_table_candidate(node)
    }

    fn jump_top(&mut self) {
        let render = self.build_render(80);
        if let Some(first) = render.vertical_items.first() {
            self.focus = focus_for_vertical_item(first, &self.focus);
        }
    }

    fn jump_bottom(&mut self) {
        let render = self.build_render(80);
        if let Some(last) = render.vertical_items.last() {
            self.focus = match &last.key {
                VerticalItemKey::TreeNode(path) => Focus::TreeNode {
                    path: path.clone(),
                    toggle: false,
                },
                VerticalItemKey::TableToggle(path) => Focus::TableToggle { path: path.clone() },
                VerticalItemKey::TableRow { path, row } => Focus::TableCell {
                    path: path.clone(),
                    row: *row,
                    column: last.column_count.saturating_sub(1),
                },
            };
        }
    }
}

impl TerminalGuard {
    fn enter(&mut self) -> io::Result<()> {
        if self.fullscreen {
            execute!(self.stdout, EnterAlternateScreen)?;
        }
        write!(self.stdout, "\u{1b}[?7l")?;
        execute!(self.stdout, EnableMouseCapture, Hide)?;
        self.stdout.flush()?;
        Ok(())
    }

    fn leave(&mut self) -> io::Result<()> {
        write!(self.stdout, "\u{1b}[?7h")?;
        execute!(self.stdout, DisableMouseCapture, Show)?;
        if self.fullscreen {
            execute!(self.stdout, LeaveAlternateScreen)?;
        } else {
            let next_row = self.start_row.saturating_add(self.last_drawn_lines);
            queue!(self.stdout, MoveTo(0, next_row), Print("\r\n"))?;
        }
        self.stdout.flush()?;
        disable_raw_mode()
    }
}

fn main() {
    let exit_code = match real_main() {
        Ok(code) => code,
        Err(error) => {
            eprintln!("{error}");
            1
        }
    };
    process::exit(exit_code);
}

fn real_main() -> Result<i32, String> {
    let options = parse_options()?;
    match options.action {
        Action::Help => {
            print!("{HELP_TEXT}");
            return Ok(0);
        }
        Action::Version => {
            println!("{VERSION}");
            return Ok(0);
        }
        Action::Keybinding => {
            print!("{KEYBINDING_TEXT}");
            return Ok(0);
        }
        Action::Run => {}
    }

    let input = if let Some(file) = options.file.as_deref() {
        fs::read_to_string(file).map_err(|_| format!("Could not open file {file}"))?
    } else {
        println!("Reading from stdin...");
        io::stdout().flush().map_err(|error| error.to_string())?;
        let mut input = String::new();
        io::stdin()
            .read_to_string(&mut input)
            .map_err(|error| error.to_string())?;
        input
    };

    let parsed: Value = serde_json::from_str(&input)
        .map_err(|error| format_parse_error(&input, &error))?;
    let root = from_value(parsed);
    let mut app = App::new(root, options.fullscreen);
    app.run().map_err(|error| error.to_string())?;
    Ok(0)
}

fn parse_options() -> Result<Options, String> {
    let mut options = Options::default();
    let mut positional = Vec::new();
    let mut parse_flags = true;
    for argument in std::env::args().skip(1) {
        if parse_flags && argument == "--" {
            parse_flags = false;
            continue;
        }
        if parse_flags && argument.starts_with('-') && argument != "-" {
            match argument.as_str() {
                "-h" | "--help" => options.action = Action::Help,
                "-v" | "--version" => options.action = Action::Version,
                "-k" | "-key" | "--key" | "-keybinding" | "--keybinding" => {
                    options.action = Action::Keybinding;
                }
                "-f" | "--fullscreen" => options.fullscreen = true,
                _ => return Err("Invalid arguments".to_string()),
            }
        } else {
            positional.push(argument);
        }
    }

    if positional.len() > 1 {
        return Err("Invalid arguments".to_string());
    }
    options.file = positional.into_iter().next();
    Ok(options)
}

fn format_parse_error(input: &str, error: &serde_json::Error) -> String {
    if input.trim().is_empty() {
        return "[json.exception.parse_error.101] parse error at line 1, column 1: attempting to parse an empty input; check that your input string or stream contains the expected JSON".to_string();
    }
    let line = error.line();
    let column = error.column();
    format!(
        "[json.exception.parse_error.101] parse error at line {line}, column {column}: {}",
        error
    )
}

fn from_value(value: Value) -> JsonNode {
    match value {
        Value::Null => JsonNode::Null,
        Value::Bool(value) => JsonNode::Bool(value),
        Value::Number(value) => JsonNode::Number(value.to_string()),
        Value::String(value) => JsonNode::String(value),
        Value::Array(values) => JsonNode::Array(values.into_iter().map(from_value).collect()),
        Value::Object(map) => {
            let mut entries = map.into_iter().collect::<Vec<_>>();
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            JsonNode::Object(
                entries
                    .into_iter()
                    .map(|(name, value)| (name, from_value(value)))
                    .collect(),
            )
        }
    }
}

fn collect_default_expansions(node: &JsonNode, path: &Path, expanded: &mut BTreeSet<Path>) {
    let should_expand = path.is_empty() || (path.len() == 1 && matches!(node, JsonNode::Object(_)));
    if should_expand {
        expanded.insert(path.clone());
        match node {
            JsonNode::Array(values) => {
                for (index, child) in values.iter().enumerate() {
                    let mut child_path = path.clone();
                    child_path.push(PathPart::Index(index));
                    collect_default_expansions(child, &child_path, expanded);
                }
            }
            JsonNode::Object(entries) => {
                for (name, child) in entries {
                    let mut child_path = path.clone();
                    child_path.push(PathPart::Key(name.clone()));
                    collect_default_expansions(child, &child_path, expanded);
                }
            }
            _ => {}
        }
    }
}

fn deep_expand_tree(node: &JsonNode, path: &Path, expanded: &mut BTreeSet<Path>) {
    if !is_container(node) {
        return;
    }
    expanded.insert(path.clone());
    match node {
        JsonNode::Array(values) => {
            for (index, child) in values.iter().enumerate() {
                let mut child_path = path.clone();
                child_path.push(PathPart::Index(index));
                deep_expand_tree(child, &child_path, expanded);
            }
        }
        JsonNode::Object(entries) => {
            for (name, child) in entries {
                let mut child_path = path.clone();
                child_path.push(PathPart::Key(name.clone()));
                deep_expand_tree(child, &child_path, expanded);
            }
        }
        _ => {}
    }
}

fn deep_expand_cell(node: &JsonNode, root: &TableCellPath, expanded: &mut BTreeSet<TableCellPath>) {
    if !is_container(node) {
        return;
    }
    expanded.insert(root.clone());
    match node {
        JsonNode::Array(values) => {
            for (index, child) in values.iter().enumerate() {
                let mut child_root = root.clone();
                child_root.inner_path.push(PathPart::Index(index));
                deep_expand_cell(child, &child_root, expanded);
            }
        }
        JsonNode::Object(entries) => {
            for (name, child) in entries {
                let mut child_root = root.clone();
                child_root.inner_path.push(PathPart::Key(name.clone()));
                deep_expand_cell(child, &child_root, expanded);
            }
        }
        _ => {}
    }
}

fn get_node<'a>(node: &'a JsonNode, path: &[PathPart]) -> Option<&'a JsonNode> {
    let mut current = node;
    for part in path {
        current = match (current, part) {
            (JsonNode::Array(values), PathPart::Index(index)) => values.get(*index)?,
            (JsonNode::Object(entries), PathPart::Key(name)) => {
                entries.iter().find(|(key, _)| key == name)?.1.borrow()
            }
            _ => return None,
        };
    }
    Some(current)
}

trait BorrowExt<T> {
    fn borrow(&self) -> &T;
}

impl<T> BorrowExt<T> for T {
    fn borrow(&self) -> &T {
        self
    }
}

fn is_container(node: &JsonNode) -> bool {
    matches!(node, JsonNode::Array(_) | JsonNode::Object(_))
}

fn primitive_face(node: &JsonNode) -> Face {
    let fg = match node {
        JsonNode::Null => Some(NULL_COLOR),
        JsonNode::Bool(_) => Some(BOOL_COLOR),
        JsonNode::Number(_) => Some(NUMBER_COLOR),
        JsonNode::String(_) => Some(STRING_COLOR),
        _ => None,
    };
    Face {
        fg,
        ..Face::default()
    }
}

fn serialize_node(node: &JsonNode) -> String {
    match node {
        JsonNode::Null => "null".to_string(),
        JsonNode::Bool(value) => value.to_string(),
        JsonNode::Number(value) => value.clone(),
        JsonNode::String(value) => serde_json::to_string(value).unwrap_or_else(|_| "\"\"".to_string()),
        JsonNode::Array(_) => "[...]".to_string(),
        JsonNode::Object(_) => "{...}".to_string(),
    }
}

fn collapsed_marker(node: &JsonNode) -> &'static str {
    match node {
        JsonNode::Array(_) => "[...]",
        JsonNode::Object(_) => "{...}",
        _ => "",
    }
}

#[derive(Clone, Debug)]
struct Prefix {
    parts: Vec<(String, Face)>,
    width: usize,
}

fn line_prefix(depth: usize, key: Option<&str>) -> Prefix {
    let mut parts = Vec::new();
    let indent = " ".repeat(depth * 2);
    let mut width = indent.width();
    parts.push((indent, Face::default()));
    if let Some(key) = key {
        let quoted = serde_json::to_string(key).unwrap_or_else(|_| "\"\"".to_string());
        width += quoted.width() + 2;
        parts.push((
            quoted,
            Face {
                fg: Some(KEY_COLOR),
                ..Face::default()
            },
        ));
        parts.push((": ".to_string(), Face::default()));
    }
    Prefix { parts, width }
}

fn continuation_prefix(depth: usize, key: Option<&str>) -> Prefix {
    let mut parts = Vec::new();
    let indent = " ".repeat(depth * 2);
    let mut width = indent.width();
    parts.push((indent, Face::default()));
    if let Some(key) = key {
        let quoted = serde_json::to_string(key).unwrap_or_else(|_| "\"\"".to_string());
        let spaces = " ".repeat(quoted.width());
        width += spaces.width() + 2;
        parts.push((
            spaces,
            Face {
                fg: Some(KEY_COLOR),
                ..Face::default()
            },
        ));
        parts.push(("  ".to_string(), Face::default()));
    }
    Prefix { parts, width }
}

fn prefix_width(depth: usize, key: Option<&str>) -> usize {
    line_prefix(depth, key).width
}

fn push_prefix(line: &mut StyledLine, prefix: &Prefix) {
    for (text, face) in &prefix.parts {
        line.push(text.clone(), face.clone());
    }
}

fn push_indent(line: &mut StyledLine, depth: usize) {
    line.push(" ".repeat(depth * 2), Face::default());
}

fn push_spaces(line: &mut StyledLine, count: usize) {
    if count > 0 {
        line.push(" ".repeat(count), Face::default());
    }
}

fn write_styled_line<W: Write>(writer: &mut W, line: &StyledLine, width: usize) -> io::Result<()> {
    let mut current_face = Face::default();
    let mut consumed = 0usize;
    for segment in &line.segments {
        if consumed >= width {
            break;
        }
        let clipped = clip_to_width(&segment.text, width - consumed);
        if clipped.is_empty() {
            continue;
        }
        apply_face(writer, &segment.face, &current_face)?;
        current_face = segment.face.clone();
        queue!(writer, Print(clipped.as_str()))?;
        consumed += UnicodeWidthStr::width(clipped.as_str());
    }
    reset_face(writer)?;
    Ok(())
}

fn apply_face<W: Write>(writer: &mut W, next: &Face, current: &Face) -> io::Result<()> {
    if current.fg != next.fg {
        if let Some(color) = next.fg {
            queue!(writer, SetForegroundColor(color))?;
        } else {
            queue!(writer, crossterm::style::ResetColor)?;
        }
    }
    if current.bold != next.bold {
        queue!(
            writer,
            SetAttribute(if next.bold {
                Attribute::Bold
            } else {
                Attribute::NormalIntensity
            })
        )?;
    }
    if current.reverse != next.reverse {
        queue!(
            writer,
            SetAttribute(if next.reverse {
                Attribute::Reverse
            } else {
                Attribute::NoReverse
            })
        )?;
    }
    Ok(())
}

fn reset_face<W: Write>(writer: &mut W) -> io::Result<()> {
    queue!(
        writer,
        crossterm::style::ResetColor,
        SetAttribute(Attribute::NormalIntensity),
        SetAttribute(Attribute::NoReverse)
    )
}

fn clip_to_width(input: &str, width: usize) -> String {
    let mut out = String::new();
    let mut used = 0usize;
    for character in input.chars() {
        let char_width = UnicodeWidthChar::width(character).unwrap_or(0);
        if used + char_width > width {
            break;
        }
        out.push(character);
        used += char_width;
    }
    out
}

fn wrap_text(text: &str, first_width: usize, next_width: usize) -> Vec<String> {
    let mut remaining = text;
    let mut result = Vec::new();
    let mut current_width = first_width.max(1);
    while !remaining.is_empty() {
        let (chunk, rest) = split_to_width(remaining, current_width);
        result.push(chunk.to_string());
        remaining = rest;
        current_width = next_width.max(1);
    }
    if result.is_empty() {
        result.push(String::new());
    }
    result
}

fn split_to_width(input: &str, width: usize) -> (&str, &str) {
    let mut used = 0usize;
    let mut split = 0usize;
    for (index, character) in input.char_indices() {
        let char_width = UnicodeWidthChar::width(character).unwrap_or(0);
        if used + char_width > width {
            break;
        }
        used += char_width;
        split = index + character.len_utf8();
    }
    if split == 0 {
        let first_len = input.chars().next().map(|c| c.len_utf8()).unwrap_or(0);
        (&input[..first_len], &input[first_len..])
    } else {
        (&input[..split], &input[split..])
    }
}

fn table_columns(node: &JsonNode) -> Vec<String> {
    let JsonNode::Array(values) = node else {
        return Vec::new();
    };
    let mut columns = BTreeSet::new();
    for value in values {
        let JsonNode::Object(entries) = value else {
            return Vec::new();
        };
        for (name, _) in entries {
            columns.insert(name.clone());
        }
    }
    columns.into_iter().collect()
}

fn is_table_candidate(node: &JsonNode) -> bool {
    let JsonNode::Array(values) = node else {
        return false;
    };
    !values.is_empty() && values.iter().all(|value| matches!(value, JsonNode::Object(_)))
}

fn table_value<'a>(node: &'a JsonNode, row: usize, column: &str) -> Option<&'a JsonNode> {
    let JsonNode::Array(rows) = node else {
        return None;
    };
    let JsonNode::Object(entries) = rows.get(row)? else {
        return None;
    };
    entries.iter().find(|(name, _)| name == column).map(|(_, value)| value)
}

fn table_border_line(indent: usize, widths: &[usize], left: char, middle: char, right: char) -> StyledLine {
    let mut line = StyledLine::default();
    push_spaces(&mut line, indent);
    line.push(left.to_string(), Face::default());
    for (index, width) in widths.iter().enumerate() {
        line.push("━".repeat(*width), Face::default());
        if index + 1 == widths.len() {
            line.push(right.to_string(), Face::default());
        } else {
            line.push(middle.to_string(), Face::default());
        }
    }
    line
}

fn table_header_line(indent: usize, index_width: usize, columns: &[String], widths: &[usize]) -> StyledLine {
    let mut line = StyledLine::default();
    push_spaces(&mut line, indent);
    line.push(
        " ".repeat(index_width),
        Face {
            fg: Some(HINT_COLOR),
            ..Face::default()
        },
    );
    line.push("┃", Face::default());
    for (column, width) in columns.iter().zip(widths.iter()) {
        line.push(column.clone(), Face::default());
        if *width > column.width() {
            push_spaces(&mut line, *width - column.width());
        }
        line.push("┃", Face::default());
    }
    line
}

fn block_max_width(block: &[StyledLine]) -> usize {
    block.iter().map(line_width).max().unwrap_or(0)
}

fn line_width(line: &StyledLine) -> usize {
    line.width
}

fn append_segments_with_optional_reverse(target: &mut StyledLine, line: &StyledLine, reverse: bool) {
    for segment in &line.segments {
        target.push(segment.text.clone(), segment.face.with_reverse(reverse));
    }
}

fn render_embedded_value(
    node: &JsonNode,
    root: &TableCellPath,
    expanded: &BTreeSet<TableCellPath>,
    width: usize,
    allow_defaults: bool,
) -> Vec<StyledLine> {
    let is_expanded = expanded.contains(root)
        || (allow_defaults
            && !root.inner_path.is_empty()
            && root.inner_path.len() == 1
            && matches!(node, JsonNode::Object(_)));
    match node {
        JsonNode::Null | JsonNode::Bool(_) | JsonNode::Number(_) | JsonNode::String(_) => {
            let mut line = StyledLine::default();
            line.push(serialize_node(node), primitive_face(node));
            vec![line]
        }
        JsonNode::Array(values) => {
            if !is_expanded {
                let mut line = StyledLine::default();
                line.push("[...]", Face::default().with_bold());
                return vec![line];
            }
            let mut lines = Vec::new();
            let mut opening = StyledLine::default();
            opening.push("[", Face::default().with_bold());
            lines.push(opening);
            for (index, child) in values.iter().enumerate() {
                let mut child_root = root.clone();
                child_root.inner_path.push(PathPart::Index(index));
                for (line_index, child_line) in render_embedded_value(
                    child,
                    &child_root,
                    expanded,
                    width.saturating_sub(2).max(1),
                    true,
                )
                .into_iter()
                .enumerate()
                {
                    let mut line = StyledLine::default();
                    push_spaces(&mut line, 2);
                    append_segments_with_optional_reverse(&mut line, &child_line, false);
                    if line_index == 0 && index + 1 != values.len() {
                        line.push(",", Face::default());
                    }
                    lines.push(line);
                }
            }
            let mut closing = StyledLine::default();
            closing.push("]", Face::default());
            lines.push(closing);
            lines
        }
        JsonNode::Object(entries) => {
            if !is_expanded {
                let mut line = StyledLine::default();
                line.push("{...}", Face::default().with_bold());
                return vec![line];
            }
            let mut lines = Vec::new();
            let mut opening = StyledLine::default();
            opening.push("{", Face::default().with_bold());
            lines.push(opening);
            for (index, (name, child)) in entries.iter().enumerate() {
                let mut child_root = root.clone();
                child_root.inner_path.push(PathPart::Key(name.clone()));
                let child_prefix = line_prefix(1, Some(name));
                let child_lines =
                    render_embedded_value(child, &child_root, expanded, width.saturating_sub(2).max(1), true);
                for (line_index, child_line) in child_lines.into_iter().enumerate() {
                    let mut line = StyledLine::default();
                    if line_index == 0 {
                        push_prefix(&mut line, &child_prefix);
                        append_segments_with_optional_reverse(&mut line, &child_line, false);
                        if index + 1 != entries.len() {
                            line.push(",", Face::default());
                        }
                    } else {
                        push_spaces(&mut line, 2);
                        append_segments_with_optional_reverse(&mut line, &child_line, false);
                    }
                    lines.push(line);
                }
            }
            let mut closing = StyledLine::default();
            closing.push("}", Face::default());
            lines.push(closing);
            lines
        }
    }
}

fn selected_vertical_index(render: &RenderOutput, focus: &Focus) -> usize {
    render
        .vertical_items
        .iter()
        .position(|item| matches_focus(item, focus))
        .unwrap_or(0)
}

fn selected_line_index(render: &RenderOutput, focus: &Focus) -> usize {
    render
        .vertical_items
        .iter()
        .find(|item| matches_focus(item, focus))
        .map(|item| item.start_line)
        .unwrap_or(0)
}

fn matches_focus(item: &VerticalItem, focus: &Focus) -> bool {
    match (&item.key, focus) {
        (VerticalItemKey::TreeNode(path), Focus::TreeNode { path: focus_path, .. }) => path == focus_path,
        (VerticalItemKey::TableToggle(path), Focus::TableToggle { path: focus_path }) => path == focus_path,
        (
            VerticalItemKey::TableRow { path, row },
            Focus::TableCell {
                path: focus_path,
                row: focus_row,
                ..
            },
        ) => path == focus_path && row == focus_row,
        _ => false,
    }
}

fn focus_for_vertical_item(item: &VerticalItem, current_focus: &Focus) -> Focus {
    match &item.key {
        VerticalItemKey::TreeNode(path) => Focus::TreeNode {
            path: path.clone(),
            toggle: false,
        },
        VerticalItemKey::TableToggle(path) => Focus::TableToggle { path: path.clone() },
        VerticalItemKey::TableRow { path, row } => {
            let column = match current_focus {
                Focus::TableCell { column, .. } => (*column).min(item.column_count.saturating_sub(1)),
                _ => 0,
            };
            Focus::TableCell {
                path: path.clone(),
                row: *row,
                column,
            }
        }
    }
}

fn is_descendant(parent: &Path, candidate: &Path) -> bool {
    candidate.len() > parent.len() && candidate.starts_with(parent)
}

fn is_descendant_or_same(parent: &Path, candidate: &Path) -> bool {
    candidate.len() >= parent.len() && candidate.starts_with(parent)
}

fn tree_toggle_start(path: &Path) -> usize {
    path.len() * 2 + 8
}

fn detect_table_column(_path: &Path, columns: &[String], column: usize) -> usize {
    if columns.is_empty() {
        return 0;
    }
    let mut offset = 0usize;
    for (index, name) in columns.iter().enumerate() {
        let width = name.width().max(5);
        let next = offset + width + 1;
        if column < next {
            return index;
        }
        offset = next;
    }
    columns.len().saturating_sub(1)
}

