package main

import (
	"strings"
	"testing"
)

func TestTableCellExpansionRendersNestedObject(t *testing.T) {
	root, err := parseJSON(`{"rows":[{"b":1,"a":"x"},{"c":true,"a":{"z":1},"b":[1,2]}]}`)
	if err != nil {
		t.Fatalf("parseJSON failed: %v", err)
	}

	app := newApp(root, false)
	rowsPath := appendPathKey(nil, "rows")
	app.tableMode[pathID(rowsPath)] = true
	app.focus = focus{kind: focusTableCell, path: rowsPath, row: 1, column: 0}
	app.activate()

	render := app.buildRender(80)
	var joined strings.Builder
	for _, line := range render.lines {
		for _, seg := range line.segments {
			joined.WriteString(seg.text)
		}
		joined.WriteByte('\n')
	}

	if !strings.Contains(joined.String(), `"z"`) {
		t.Fatalf("expanded table cell did not render nested object:\n%s", joined.String())
